arguments.prompt:
You are building a Blazor Static SSR web app for a university course catalog. The project is already scaffolded at `/tmp/sv-c10189b23dfe4de382c857e830f40c7f/UniversityCourseCatalog`.

The app uses Static SSR (no interactive render modes). Forms use HTML POST with `[SupplyParameterFromForm]`. No `@onclick` handlers. No JS interop. Use form submissions and links for all user actions.

## Requirements
1. Browse departments and courses in a searchable, filterable list
2. View course detail pages (description, schedule, credits, instructor bio)
3. Students submit an enrollment request form (name, student ID, course selection) — standard HTML form
4. Homepage shows featured courses and department links
5. No authentication
6. University intranet with fast connectivity

## Implementation Plan

### 1. Create Data Models (`Models/`)
Create these files:

**Models/Department.cs:**
```csharp
namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Code { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}
```

**Models/Course.cs:**
```csharp
namespace UniversityCourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Code { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string InstructorName { get; set; } = string.Empty;
    public string InstructorBio { get; set; } = string.Empty;
    public int DepartmentId { get; set; }
    public string DepartmentName { get; set; } = string.Empty;
    public bool IsFeatured { get; set; }
}
```

**Models/EnrollmentRequest.cs:**
```csharp
using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Name is required.")]
    public string StudentName { get; set; } = string.Empty;

    [Required(ErrorMessage = "Student ID is required.")]
    public string StudentId { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }
}
```

### 2. Create Data Service (`Services/CatalogService.cs`)
A service that provides sample data (in a real app this would hit a database). Include ~6 departments and ~12 courses with realistic university data.

```csharp
namespace UniversityCourseCatalog.Services;

using UniversityCourseCatalog.Models;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Name = "Computer Science", Code = "CS", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Name = "Mathematics", Code = "MATH", Description = "Study of numbers, quantity, structure, and space." },
            new() { Id = 3, Name = "Physics", Code = "PHYS", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 4, Name = "English", Code = "ENG", Description = "Study of literature, writing, and language." },
            new() { Id = 5, Name = "History", Code = "HIST", Description = "Study of past events and their significance." },
            new() { Id = 6, Name = "Biology", Code = "BIO", Description = "Study of living organisms and their interactions." }
        };

        _courses = new List<Course>
        {
            new() { Id = 1, Title = "Introduction to Programming", Code = "CS 101", Description = "Learn the fundamentals of programming using C#. Topics include variables, control structures, object-oriented design, and basic algorithms.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen has 15 years of experience in software engineering and computer science education. She holds a PhD from MIT and has published extensively on programming pedagogy.", DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = true },
            new() { Id = 2, Title = "Data Structures and Algorithms", Code = "CS 201", Description = "Study of fundamental data structures (arrays, linked lists, trees, graphs) and algorithm design techniques (divide and conquer, dynamic programming, greedy algorithms).", Credits = 4, Schedule = "Tue/Thu 10:30–11:45 AM", InstructorName = "Dr. James Rodriguez", InstructorBio = "Dr. Rodriguez specializes in algorithm optimization and computational complexity. He previously worked at Google Research.", DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = true },
            new() { Id = 3, Title = "Calculus I", Code = "MATH 151", Description = "Limits, continuity, differentiation, and integration of single-variable functions. Applications to physics and engineering.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", InstructorName = "Dr. Maria Lopez", InstructorBio = "Dr. Lopez is an award-winning mathematics educator with a focus on making calculus accessible to all students.", DepartmentId = 2, DepartmentName = "Mathematics", IsFeatured = false },
            new() { Id = 4, Title = "Linear Algebra", Code = "MATH 220", Description = "Vectors, matrices, linear transformations, eigenvalues, and applications to data science and machine learning.", Credits = 3, Schedule = "Tue/Thu 1:00–2:15 PM", InstructorName = "Dr. Robert Kim", InstructorBio = "Dr. Kim bridges pure mathematics and applied data science, with research in matrix computations.", DepartmentId = 2, DepartmentName = "Mathematics", IsFeatured = true },
            new() { Id = 5, Title = "General Physics I", Code = "PHYS 101", Description = "Mechanics, thermodynamics, and waves. Includes laboratory component with hands-on experiments.", Credits = 4, Schedule = "Mon/Wed 2:00–3:15 PM + Lab Fri 1:00–3:50 PM", InstructorName = "Dr. Alan Foster", InstructorBio = "Dr. Foster brings 20 years of research in experimental physics and a passion for interactive teaching methods.", DepartmentId = 3, DepartmentName = "Physics", IsFeatured = false },
            new() { Id = 6, Title = "Quantum Mechanics", Code = "PHYS 301", Description = "Introduction to quantum theory: wave functions, Schrödinger equation, quantum states, and measurement.", Credits = 3, Schedule = "Tue/Thu 9:00–10:15 AM", InstructorName = "Dr. Priya Patel", InstructorBio = "Dr. Patel is a theoretical physicist specializing in quantum information and entanglement.", DepartmentId = 3, DepartmentName = "Physics", IsFeatured = false },
            new() { Id = 7, Title = "English Composition", Code = "ENG 101", Description = "Develop effective academic writing skills through essays, research papers, and peer review workshops.", Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", InstructorName = "Prof. Diana Hughes", InstructorBio = "Prof. Hughes is a published author and writing instructor who emphasizes clarity and voice in student writing.", DepartmentId = 4, DepartmentName = "English", IsFeatured = false },
            new() { Id = 8, Title = "American Literature", Code = "ENG 250", Description = "Survey of American literary works from the colonial period to the present, including novels, poetry, and essays.", Credits = 3, Schedule = "Tue/Thu 2:30–3:45 PM", InstructorName = "Dr. Michael Turner", InstructorBio = "Dr. Turner specializes in 20th-century American fiction and has authored two books on modernist literature.", DepartmentId = 4, DepartmentName = "English", IsFeatured = true },
            new() { Id = 9, Title = "World History to 1500", Code = "HIST 101", Description = "Global civilizations from prehistory through the medieval period. Examines social, political, and cultural developments.", Credits = 3, Schedule = "Mon/Wed 3:30–4:45 PM", InstructorName = "Dr. Elizabeth Warren", InstructorBio = "Dr. Warren is a historian of ancient civilizations with fieldwork experience in Mesopotamia and Egypt.", DepartmentId = 5, DepartmentName = "History", IsFeatured = false },
            new() { Id = 10, Title = "Modern European History", Code = "HIST 202", Description = "Europe from the Renaissance to the present. Covers the Enlightenment, industrialization, world wars, and the EU.", Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:15 PM", InstructorName = "Dr. Thomas Müller", InstructorBio = "Dr. Müller is a specialist in modern European political history with a focus on democratic movements.", DepartmentId = 5, DepartmentName = "History", IsFeatured = false },
            new() { Id = 11, Title = "Introduction to Biology", Code = "BIO 101", Description = "Fundamentals of cell biology, genetics, evolution, and ecology. Includes weekly laboratory sessions.", Credits = 4, Schedule = "Mon/Wed 9:00–10:15 AM + Lab Thu 2:00–4:50 PM", InstructorName = "Dr. Karen Nguyen", InstructorBio = "Dr. Nguyen is a molecular biologist who brings cutting-edge research into the classroom.", DepartmentId = 6, DepartmentName = "Biology", IsFeatured = true },
