### 5. Create Pages

**Delete** `Components/Pages/Counter.razor`, `Components/Pages/Weather.razor`, and `Components/Pages/Error.razor` if they exist but KEEP `Home.razor`.

**Replace Components/Pages/Home.razor:**
```razor
@page "/"
@inject UniversityCourseCatalog.Services.CatalogService CatalogService

<PageTitle>Home - University Course Catalog</PageTitle>

<section class="hero">
    <h1>Welcome to the University Course Catalog</h1>
    <p>Explore our departments, browse courses, and submit your enrollment request.</p>
</section>

<section class="featured-courses">
    <h2>Featured Courses</h2>
    <div class="course-grid">
        @foreach (var course in CatalogService.GetFeaturedCourses())
        {
            <div class="course-card">
                <span class="badge">@course.Code</span>
                <h3><a href="/courses/@course.Id">@course.Title</a></h3>
                <p>@course.Credits credits · @course.DepartmentName</p>
                <p class="schedule">@course.Schedule</p>
            </div>
        }
    </div>
</section>

<section class="departments-section">
    <h2>Departments</h2>
    <div class="dept-grid">
        @foreach (var dept in CatalogService.GetDepartments())
        {
            <a href="/departments/@dept.Id" class="dept-link">
                <strong>@dept.Code</strong>
                <span>@dept.Name</span>
            </a>
        }
    </div>
</section>
```

**Create Components/Pages/Courses.razor:**
```razor
@page "/courses"
@inject UniversityCourseCatalog.Services.CatalogService CatalogService

<PageTitle>Browse Courses - University Course Catalog</PageTitle>

<h1>Browse Courses</h1>

<form method="get" action="/courses" class="search-form">
    <input type="text" name="search" value="@Search" placeholder="Search courses..." />
    <select name="departmentId">
        <option value="">All Departments</option>
        @foreach (var dept in CatalogService.GetDepartments())
        {
            <option value="@dept.Id" selected="@(DepartmentId == dept.Id)">@dept.Name</option>
        }
    </select>
    <button type="submit">Search</button>
</form>

@{
    var courses = CatalogService.SearchCourses(Search, DepartmentId);
}

<p class="results-count">Showing @courses.Count course(s)</p>

<div class="course-list">
    @foreach (var course in courses)
    {
        <div class="course-item">
            <div class="course-item-header">
                <span class="badge">@course.Code</span>
                <span class="credits">@course.Credits credits</span>
            </div>
            <h3><a href="/courses/@course.Id">@course.Title</a></h3>
            <p>@course.DepartmentName · @course.InstructorName</p>
            <p class="schedule">@course.Schedule</p>
        </div>
    }
</div>

@if (courses.Count == 0)
{
    <p class="no-results">No courses found matching your criteria.</p>
}

@code {
    [SupplyParameterFromQuery] public string? Search { get; set; }
    [SupplyParameterFromQuery] public int? DepartmentId { get; set; }
}
```

