**Create Components/Pages/Enroll.razor:**
```razor
@page "/enroll"
@inject UniversityCourseCatalog.Services.CatalogService CatalogService

<PageTitle>Enrollment Request - University Course Catalog</PageTitle>

<h1>Enrollment Request</h1>

@if (Submitted)
{
    <div class="success-message">
        <h2>Request Submitted!</h2>
        <p>Thank you, <strong>@Model.StudentName</strong>. Your enrollment request for <strong>@CatalogService.GetCourse(Model.CourseId)?.Title</strong> has been received.</p>
        <p>You will receive a confirmation at your university email.</p>
        <a href="/courses">Browse more courses</a>
    </div>
}
else
{
    <p>Fill out the form below to submit an enrollment request.</p>

    <EditForm method="post" Model="Model" OnValidSubmit="HandleSubmit" FormName="enrollment" class="enroll-form">
        <DataAnnotationsValidator />
        <AntiforgeryToken />

        <div class="form-group">
            <label for="studentName">Full Name</label>
            <InputText id="studentName" @bind-Value="Model.StudentName" />
            <ValidationMessage For="() => Model.StudentName" />
        </div>

        <div class="form-group">
            <label for="studentId">Student ID</label>
            <InputText id="studentId" @bind-Value="Model.StudentId" placeholder="e.g., STU-12345" />
            <ValidationMessage For="() => Model.StudentId" />
        </div>

        <div class="form-group">
            <label for="courseId">Course</label>
            <InputSelect id="courseId" @bind-Value="Model.CourseId">
                <option value="0">-- Select a course --</option>
                @foreach (var course in CatalogService.GetCourses())
                {
                    <option value="@course.Id">@course.Code — @course.Title (@course.Credits cr)</option>
                }
            </InputSelect>
            <ValidationMessage For="() => Model.CourseId" />
        </div>

        <button type="submit">Submit Enrollment Request</button>
    </EditForm>
}

@code {
    [SupplyParameterFromForm] public EnrollmentRequest Model { get; set; } = new();
    [SupplyParameterFromQuery] public int? CourseId { get; set; }

    private bool Submitted { get; set; }

    protected override void OnInitialized()
    {
        if (CourseId.HasValue && Model.CourseId == 0)
            Model.CourseId = CourseId.Value;
    }

    private void HandleSubmit()
    {
        Submitted = true;
    }
}
```

