            new() { Id = 3, Title = "Calculus I", Code = "MATH 151", Description = "Limits, continuity, differentiation, and integration of single-variable functions. Applications to physics and engineering.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", InstructorName = "Dr. Maria Lopez", InstructorBio = "Dr. Lopez is an award-winning mathematics educator with a focus on making calculus accessible to all students.", DepartmentId = 2, DepartmentName = "Mathematics", IsFeatured = false },
